import { sql } from "drizzle-orm";
import {
  check,
  index,
  integer,
  pgTable,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";

import { users } from "./auth";
import { books } from "./books";

/**
 * One continuous stretch of reading. The id is generated by the browser, so
 * every report is an idempotent upsert (safe to retry; works while unloading).
 * `ended_at` is the time of the last user activity, never "now".
 */
export const readingSessions = pgTable(
  "reading_sessions",
  {
    id: uuid().primaryKey(),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    bookId: uuid()
      .notNull()
      .references(() => books.id, { onDelete: "cascade" }),
    startedAt: timestamp({ withTimezone: true }).notNull(),
    endedAt: timestamp({ withTimezone: true }).notNull(),
    /** Distinct pages the reader was on during the session. */
    pagesRead: integer().notNull().default(0),
  },
  (t) => [
    check(
      "reading_sessions_ended_after_started",
      sql`${t.endedAt} >= ${t.startedAt}`,
    ),
    index("reading_sessions_user_id_started_at_idx").on(
      t.userId,
      sql`${t.startedAt} desc`,
    ),
    index("reading_sessions_book_id_idx").on(t.bookId),
  ],
);
